import{_ as e,o as a,c as r,aA as i}from"./chunks/framework.BMzE2Z9R.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","sidebar":false,"hero":{"name":"中国通用人工智能协会","text":"AGI Society of China","tagline":"非公理推理系统 · 通用人工智能理论 · 开源实现","actions":[{"theme":"brand","text":"探索知识库","link":"/nars/"},{"theme":"alt","text":"最新会议","link":"/conference/"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1778415461000}'),d={name:"index.md"};function s(o,t,n,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<section class="section-light"><h2 id="关于协会" tabindex="-1">关于协会 <a class="header-anchor" href="#关于协会" aria-label="Permalink to &quot;关于协会&quot;">​</a></h2><p>中国通用人工智能协会（AGI Society CN）由<strong>王培教授</strong>发起创立，致力于推动通用人工智能理论与开源实现的研究、教育与交流。协会以 <strong>NARS</strong>（Non-Axiomatic Reasoning System，非公理推理系统）为核心理论锚点，汇聚哲学、计算机科学、认知科学、教育科学等多学科力量。</p><p>自 2016 年起，协会已连续举办<strong>九届</strong>中国通用人工智能年会，并组织超过百场学术组会。</p></section><div class="section-divider"></div><section class="section-dark"><h2 id="核心研究" tabindex="-1">核心研究 <a class="header-anchor" href="#核心研究" aria-label="Permalink to &quot;核心研究&quot;">​</a></h2><div class="research-grid"><div class="research-card"><h3 id="nars-理论" tabindex="-1">NARS 理论 <a class="header-anchor" href="#nars-理论" aria-label="Permalink to &quot;NARS 理论&quot;">​</a></h3><p>基于 <strong>AIKR</strong>（不足知识与资源预设）与 <strong>3C 原则</strong>（正确性、具体性、紧凑性），NARS 是一种不同于主流机器学习的通用人工智能路径。它强调在<strong>实时、开放、资源有限</strong>的条件下进行自适应推理。</p><p><a href="/nars/">探索 NARS 理论 →</a></p></div><div class="research-card"><h3 id="nars-工程实现" tabindex="-1">NARS 工程实现 <a class="header-anchor" href="#nars-工程实现" aria-label="Permalink to &quot;NARS 工程实现&quot;">​</a></h3><p>全球开发者社区已实现 <strong>12 种</strong>跨语言 NARS 版本，覆盖 C、Clojure、Java、JavaScript、Julia、Python、Rust、Swift 等主流语言。</p><p><a href="/nars/impl/">查看实现列表 →</a></p></div></div></section><div class="section-divider"></div><section class="section-light"><h2 id="学术会议" tabindex="-1">学术会议 <a class="header-anchor" href="#学术会议" aria-label="Permalink to &quot;学术会议&quot;">​</a></h2><div class="conference-highlight"><h3 id="第九届中国通用人工智能年会" tabindex="-1">第九届中国通用人工智能年会 <a class="header-anchor" href="#第九届中国通用人工智能年会" aria-label="Permalink to &quot;第九届中国通用人工智能年会&quot;">​</a></h3><p><strong>2024 年 7 月 · 南京理工大学</strong></p><p>中国通用人工智能年会是国内 AGI 领域最具影响力的学术会议之一，每年汇聚国内外 AGI 研究者、开发者和哲学学者，围绕通用人工智能的理论基础、工程实践与跨学科影响展开深度讨论。</p><p><a href="/conference/2024">查看年会详情 →</a></p></div><div class="conference-archive"><h3 id="往届年会" tabindex="-1">往届年会 <a class="header-anchor" href="#往届年会" aria-label="Permalink to &quot;往届年会&quot;">​</a></h3><table tabindex="0"><thead><tr><th>届次</th><th>年份</th><th>地点</th></tr></thead><tbody><tr><td>第九届</td><td>2024</td><td>南京理工大学</td></tr><tr><td>第八届</td><td>2023</td><td>上海复旦大学</td></tr><tr><td>第七届</td><td>2022</td><td>线上会议</td></tr><tr><td>第六届</td><td>2021</td><td>线上会议</td></tr><tr><td>第五届</td><td>2020</td><td>线上会议</td></tr><tr><td>第四届</td><td>2019</td><td>厦门大学</td></tr><tr><td>第三届</td><td>2018</td><td>西安交通大学</td></tr><tr><td>第二届</td><td>2017</td><td>北京大学</td></tr><tr><td>第一届</td><td>2016</td><td>华中师范大学</td></tr></tbody></table><p><a href="/conference/">查看全部年会记录 →</a></p></div></section><div class="section-divider"></div><section class="section-dark"><h2 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h2><div class="knowledge-grid"><div class="knowledge-card"><h3 id="思想书库" tabindex="-1">思想书库 <a class="header-anchor" href="#思想书库" aria-label="Permalink to &quot;思想书库&quot;">​</a></h3><p>意义片网思想、拟态操作、Lazero、类脑智能意识系统、智能同一观——跨学科的 AGI 理论探索。</p><p><a href="/other/">浏览思想书库 →</a></p></div><div class="knowledge-card"><h3 id="组会视频" tabindex="-1">组会视频 <a class="header-anchor" href="#组会视频" aria-label="Permalink to &quot;组会视频&quot;">​</a></h3><p>2016–2025 历年组会视频目录，覆盖 NARS 理论研读、论文分享、工程进展报告，全部 B 站可看。</p><p><a href="/conference/group_meeting_catalogue">查看组会目录 →</a></p></div><div class="knowledge-card"><h3 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h3><p>大语言模型、认知架构、意识理论、计算精神病学——AGI 关联前沿议题的持续追踪。</p><p><a href="/sai/">浏览前沿研究 →</a></p></div></div></section><div class="section-divider"></div><section class="section-light"><h2 id="核心成员" tabindex="-1">核心成员 <a class="header-anchor" href="#核心成员" aria-label="Permalink to &quot;核心成员&quot;">​</a></h2><div class="team-grid"><div class="team-member"><p><strong>王培</strong> · 教授 <em>美国天普大学计算机系</em> NARS 理论创始人，AGI 协会发起人</p></div><div class="team-member"><p><strong>刘凯</strong> · 博士 <em>渤海大学教育科学学院</em> 协会召集人，通用人工智能与教育</p></div><div class="team-member"><p><strong>徐英瑾</strong> · 教授 <em>复旦大学哲学学院</em> 人工智能哲学，心灵哲学</p></div><div class="team-member"><p><strong>那迪</strong> · 博士 <em>西北民族大学</em> 智能决策，数据科学，AGI 理论</p></div><div class="team-member"><p><strong>魏屹东</strong> · 教授 <em>山西大学哲学学院</em> 适应性表征，认知哲学</p></div><div class="team-member"><p><strong>李祥</strong> · 博士 <em>辽宁工业大学</em> AGI 认知科学，人工智能情感</p></div></div></section><div class="section-divider"></div><section class="section-dark"><h2 id="参与贡献" tabindex="-1">参与贡献 <a class="header-anchor" href="#参与贡献" aria-label="Permalink to &quot;参与贡献&quot;">​</a></h2><p>本知识库内容开放编辑。欢迎到 <a href="https://github.com/Hailaylin/agi-society-cn" target="_blank" rel="noreferrer">GitHub</a> 或 <a href="https://gitee.com/Hailay/agi-society-cn" target="_blank" rel="noreferrer">Gitee</a> 提交 Pull Request。</p><p>查看<a href="/about/contributing/formats">贡献者指南</a>了解编辑方式。</p></section><hr><div class="home-footer"><p><em>本知识库基于 Nólëbase (VitePress) 构建 · 内容采用 <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a> 许可 · 粤ICP备2021145979号-1</em></p></div>',13)])])}const g=e(d,[["render",s]]);export{p as __pageData,g as default};
